const evidence=[
  {id:'claim_apac_scale',title:'APAC engineering scale-up',detail:'Built an engineering organisation across 3 countries; grew platform team from 18 to 67.',status:'Source-backed'},
  {id:'claim_merger',title:'Post-merger platform consolidation',detail:'Consolidated platform teams and operating processes after an acquisition.',status:'Self-attested'},
  {id:'claim_cost',title:'Infrastructure economics',detail:'Reduced infrastructure operating cost by 28% during platform modernization.',status:'Corroborated'}
];

const dispositions=Object.fromEntries(opportunities.map(o=>[o.id,'discovered']));
let activeFilter='shortlist';let selectedOpportunityId=opportunities[0].id;let selectedEvidence=new Set();let researchOpen=new Set();let compareSelection=new Set();
const stateLabel={discovered:'New',watching:'Saved',exploring:'Under review',pursuing:'Active',passed:'Closed',closed:'Closed'};
const byId=id=>opportunities.find(o=>o.id===id);
function log(type,detail={}){const e={t_ms:Math.round(performance.now()-startedAt),type,...detail};session.events.push(e);renderEvents()}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1500)}
function showView(name){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(`${name}View`).classList.add('active');document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name))}

function renderBriefing(){
  const groups=['Needs a decision','Due today'];
  document.getElementById('briefingGroups').innerHTML=groups.map(group=>{
    const items=opportunities.filter(o=>o.briefingGroup===group);
    return `<section class="brief-group"><div class="group-label" data-kind="${group}"><strong>${group}</strong><span>${items.length}</span></div>${items.map(o=>`<div class="brief-item"><div class="brief-event">${o.briefEvent}<small>${o.updated}</small></div><div class="brief-role"><strong>${o.role}</strong><span>${o.company} · ${o.location}</span></div><div class="brief-fact">${o.briefing}</div><div class="brief-meta"><strong>${o.routeShort}</strong><span>${o.trajectory}</span></div><button class="text-btn" data-brief-cta="${o.briefCta==='Prepare for call'?'prepare_call':'open_brief'}" data-opportunity="${o.id}">${o.briefCta} →</button></div>`).join('')}</section>`;
  }).join('');
  document.querySelectorAll('[data-brief-cta]').forEach(b=>b.onclick=()=>openOpportunity(b.dataset.opportunity,b.dataset.briefCta));
}
function filterMatches(o){const s=dispositions[o.id];if(activeFilter==='all')return true;if(activeFilter==='shortlist')return o.shortlisted&&!['passed','closed'].includes(s);if(activeFilter==='saved')return s==='watching';if(activeFilter==='pursuing')return s==='pursuing';if(activeFilter==='closed')return ['passed','closed'].includes(s);return true}
function updateCounts(){const shortlist=opportunities.filter(o=>o.shortlisted&&!['passed','closed'].includes(dispositions[o.id])).length;document.getElementById('countShortlist').textContent=shortlist;document.getElementById('scanShortlistCount').textContent=shortlist;document.getElementById('countAll').textContent=opportunities.length;document.getElementById('countSaved').textContent=opportunities.filter(o=>dispositions[o.id]==='watching').length;document.getElementById('countPursuing').textContent=opportunities.filter(o=>dispositions[o.id]==='pursuing').length;document.getElementById('countClosed').textContent=opportunities.filter(o=>['passed','closed'].includes(dispositions[o.id])).length}
function renderOpportunityList(){
  const items=opportunities.filter(filterMatches);if(items.length&&!items.some(o=>o.id===selectedOpportunityId))selectedOpportunityId=items[0].id;
  document.getElementById('oppList').innerHTML=items.length?items.map(o=>{const s=dispositions[o.id];return `<div class="opp-row ${o.id===selectedOpportunityId?'selected':''}" data-row="${o.id}"><label class="row-check" title="Compare"><input type="checkbox" data-compare="${o.id}" ${compareSelection.has(o.id)?'checked':''}></label><button class="row-main" data-select="${o.id}" style="border:0;background:none;text-align:left;padding:0"><strong>${o.role}</strong><span>${o.company} · ${o.location}</span><small>${o.briefing}</small></button><div class="row-signal"><b>${o.trajectory}</b><span>${o.routeShort}</span></div><div class="row-updated"><b class="row-fresh">${o.fresh}</b>${o.updated}<br><button class="row-pin ${o.shortlisted?'active':''}" data-pin="${o.id}" title="${o.shortlisted?'Remove from shortlist':'Add to shortlist'}">${o.shortlisted?'★':'☆'}</button></div></div>`}).join(''):'<div class="arg-section">Nothing here yet.</div>';
  document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedOpportunityId=b.dataset.select;log('opportunity_selected',{opportunity_id:selectedOpportunityId});renderOpportunityList();renderOpportunityDetail()});
  document.querySelectorAll('[data-compare]').forEach(c=>c.onchange=()=>{c.checked?compareSelection.add(c.dataset.compare):compareSelection.delete(c.dataset.compare);renderCompareBar();log('compare_selection_changed',{opportunity_id:c.dataset.compare,selected:c.checked})});
  document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=e=>{e.stopPropagation();const o=byId(b.dataset.pin);o.shortlisted=!o.shortlisted;log('shortlist_pin_changed',{opportunity_id:o.id,shortlisted:o.shortlisted});renderOpportunityList();updateCounts()});
  updateCounts();renderCompareBar();
}
function argRows(rows){return rows.map(([label,value])=>`<div class="arg-row"><span>${label}</span><span>${value}</span></div>`).join('')}
function sourceRows(rows){return rows.map(([name,date])=>`<div class="source-row"><span>${name}</span><span>${date}</span></div>`).join('')}
function routeRows(o){return o.routes.length?o.routes.map(r=>`<div class="route-opt"><div><strong>${r.name}</strong><span>${r.viability}</span></div><p>${r.detail}</p></div>`).join(''):'<div class="arg-row"><span>Route</span><em>No credible warm route found.</em></div>'}
function detailActions(o){const s=dispositions[o.id];if(s==='pursuing')return `<button class="btn" data-action="note">Add note</button><button class="btn primary" data-action="workspace">Open workspace</button><button class="btn quiet danger" data-action="archive">Archive</button>`;if(s==='exploring')return `<button class="btn" data-action="save">Save for later</button><button class="btn quiet" data-action="dismiss">Close</button><button class="btn primary" data-action="pursue">Open pursuit workspace</button><span class="action-note">Marks this opportunity active. Nothing is sent or submitted.</span>`;if(s==='watching')return `<button class="btn quiet" data-action="dismiss">Close</button><button class="btn primary" data-action="research">${o.cta}</button>`;return `<button class="btn quiet" data-action="dismiss">Close</button><button class="btn" data-action="save">Save for later</button><button class="btn primary" data-action="research">${o.cta}</button>`}
function renderOpportunityDetail(){
  const o=byId(selectedOpportunityId);if(!o){document.getElementById('oppDetail').innerHTML='<div class="arg-section">Select an opportunity.</div>';return}
  const s=dispositions[o.id];const deep=researchOpen.has(o.id)||['exploring','pursuing'].includes(s);const ev=evidence.map(e=>`<label class="ev-opt ${selectedEvidence.has(e.id)?'selected':''}" data-evidence="${e.id}"><input type="checkbox" ${selectedEvidence.has(e.id)?'checked':''}><span><strong>${e.title}</strong> · ${e.status}<small>${e.detail}</small></span></label>`).join('');
  document.getElementById('oppDetail').innerHTML=`<div class="insp-head"><div><div class="insp-role">${o.role}</div><div class="insp-company">${o.company} · ${o.location}</div></div><div class="insp-status"><b>${stateLabel[s]}</b><span>${o.shortlisted?'★ Shortlist':'Not shortlisted'}</span></div></div><p class="argument-lead">${o.thesis}</p><section class="arg-section"><h3>Evidence for</h3>${argRows(o.caseFor)}</section><section class="arg-section"><h3>Open questions</h3>${argRows(o.watch)}</section><section class="arg-section"><h3>Route in</h3><div class="arg-row"><span>Current route</span><strong>${o.routeShort}</strong></div></section><section class="arg-section"><h3>Sources</h3>${sourceRows(o.sources)}</section><div class="actions">${detailActions(o)}</div><div id="researchBlock" class="research-block ${deep?'open':''}"><section class="arg-section"><h3>Research notes</h3><div class="research-grid"><div><strong>Supports</strong><ul class="research-list">${o.research.reasons.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><strong>Still unresolved</strong><ul class="research-list">${o.research.unknowns.map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section><section class="arg-section"><h3>Access routes</h3>${routeRows(o)}<div class="arg-row"><span>External action</span><span>Nothing has been sent.</span></div></section><section class="arg-section"><h3>Use your evidence</h3><button class="evidence-link" id="evidenceToggle">Choose relevant experience →</button><div id="evidencePicker" hidden><div class="evidence-picker">${ev}</div><button class="btn" id="bindEvidence">Use selected experience</button></div></section>${s==='pursuing'?`<div class="workspace-strip"><strong>Workspace</strong><div class="workspace-links"><span>Research</span><span>People</span><span>Positioning</span><span>Documents</span><span>Selection</span><span>Timeline</span></div></div>`:''}<div class="note-editor" id="noteEditor"><textarea placeholder="Private note"></textarea><button class="btn" id="saveNote">Save note</button></div></div>`;
  bindDetail(o);
}
function bindDetail(o){document.querySelectorAll('#oppDetail [data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,o));document.getElementById('evidenceToggle')?.addEventListener('click',()=>{const p=document.getElementById('evidencePicker');p.hidden=!p.hidden;log('evidence_picker_toggled',{opportunity_id:o.id,open:!p.hidden})});document.querySelectorAll('.ev-opt').forEach(el=>el.onclick=ev=>{if(ev.target.tagName!=='INPUT')ev.preventDefault();const id=el.dataset.evidence;selectedEvidence.has(id)?selectedEvidence.delete(id):selectedEvidence.add(id);log('evidence_toggled',{opportunity_id:o.id,evidence_id:id,selected:selectedEvidence.has(id)});renderOpportunityDetail();document.getElementById('evidencePicker').hidden=false});document.getElementById('bindEvidence')?.addEventListener('click',()=>{if(!selectedEvidence.size){toast('Choose at least one experience');return}log('evidence_bound',{opportunity_id:o.id,evidence_ids:[...selectedEvidence],truth_status_changed:false,canonical_action:'ACT-MANDATE-EVIDENCE-BIND'});toast('Experience linked. Evidence status unchanged.')});document.getElementById('saveNote')?.addEventListener('click',()=>{const text=document.querySelector('#noteEditor textarea').value.trim();if(!text){toast('Write a note first');return}log('private_note_added',{opportunity_id:o.id,length:text.length});toast('Private note saved')})}
function handleAction(action,o){if(action==='research'){dispositions[o.id]='exploring';researchOpen.add(o.id);log('disposition_changed',{opportunity_id:o.id,to:'exploring',canonical_action:'ACT-OPPORTUNITY-EXPLORE',surface_label:o.cta});renderOpportunityList();renderOpportunityDetail();return}if(action==='save'){dispositions[o.id]='watching';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'watching',canonical_action:'ACT-OPPORTUNITY-WATCH',surface_label:'Save for later'});toast('Saved for later');renderOpportunityList();renderOpportunityDetail();return}if(action==='dismiss'){dispositions[o.id]='passed';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'passed',canonical_action:'ACT-OPPORTUNITY-PASS',surface_label:'Dismiss'});toast('Closed');renderOpportunityList();renderOpportunityDetail();return}if(action==='pursue'){dispositions[o.id]='pursuing';researchOpen.add(o.id);log('disposition_changed',{opportunity_id:o.id,to:'pursuing',canonical_action:'ACT-OPPORTUNITY-PURSUE',surface_label:'Open pursuit workspace'});toast('Active — nothing sent or submitted');renderOpportunityList();renderOpportunityDetail();return}if(action==='workspace'){log('workspace_opened',{opportunity_id:o.id});renderOpportunityDetail();return}if(action==='note'){document.getElementById('noteEditor')?.classList.toggle('open');return}if(action==='archive'){dispositions[o.id]='closed';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'closed'});toast('Archived');renderOpportunityList();renderOpportunityDetail()}}
function openOpportunity(id,reason='open_brief'){selectedOpportunityId=id;activeFilter='shortlist';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.filter==='shortlist'));showView('opportunities');renderOpportunityList();renderOpportunityDetail();log('briefing_to_opportunity',{opportunity_id:id,reason})}

function renderCompareBar(){const bar=document.getElementById('compareBar');bar.hidden=compareSelection.size<2;document.getElementById('compareCount').textContent=`${compareSelection.size} selected`}
function renderCompare(){const items=[...compareSelection].map(byId).filter(Boolean);const dimensions=[['Trajectory',o=>o.trajectory],['Scope / mandate',o=>o.caseFor[0]?.[1]||o.mandate],['Route in',o=>o.routeShort],['Biggest unknown',o=>o.watch[0]?.[1]||'—'],['Source',o=>o.sources[0]?.[0]||'—'],['Candidate state',o=>stateLabel[dispositions[o.id]]]];document.getElementById('compareTable').innerHTML=`<table class="cmp-table"><thead><tr><th>Dimension</th>${items.map(o=>`<th>${o.role}<span class="cmp-sub">${o.company} · ${o.location}</span></th>`).join('')}</tr></thead><tbody>${dimensions.map(([name,get])=>`<tr><th>${name}</th>${items.map(o=>`<td>${get(o)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
document.getElementById('compareGo').onclick=()=>{renderCompare();document.getElementById('workbench').hidden=true;document.querySelector('.tabs').hidden=true;document.getElementById('compareView').hidden=false;document.getElementById('compareBar').hidden=true;log('comparison_opened',{opportunity_ids:[...compareSelection]})};document.getElementById('cmpBack').onclick=()=>{document.getElementById('compareView').hidden=true;document.getElementById('workbench').hidden=false;document.querySelector('.tabs').hidden=false;renderCompareBar()};document.getElementById('compareClear').onclick=()=>{compareSelection.clear();renderOpportunityList()};

function renderEvidence(){document.getElementById('evidenceLibrary').innerHTML=evidence.map(e=>`<div class="evidence-row"><strong>${e.title}</strong><p>${e.detail}</p><span>${e.status}</span></div>`).join('')}
function renderEvents(){const el=document.getElementById('eventLog');if(!el)return;el.innerHTML=session.events.slice().reverse().map(e=>`<div class="event"><b>${e.t_ms}ms · ${e.type}</b><br>${Object.entries(e).filter(([k])=>!['t_ms','type'].includes(k)).map(([k,v])=>`${k}: ${JSON.stringify(v)}`).join('<br>')}</div>`).join('')}

document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{activeFilter=t.dataset.filter;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));renderOpportunityList();renderOpportunityDetail();log('opportunity_filter_changed',{filter:activeFilter})});document.querySelectorAll('.nav-item').forEach(n=>n.onclick=()=>{showView(n.dataset.view);if(n.dataset.view==='opportunities'){renderOpportunityList();renderOpportunityDetail()}log('nav',{view:n.dataset.view})});
const params=new URLSearchParams(location.search);const researchMode=params.get('research')==='1';const researchToggle=document.getElementById('researchToggle'),researchPanel=document.getElementById('researchPanel');if(researchMode){researchToggle.hidden=false;researchToggle.onclick=()=>{const open=!researchPanel.classList.contains('open');researchPanel.classList.toggle('open',open);researchPanel.setAttribute('aria-hidden',String(!open))}}document.getElementById('closeResearch').onclick=()=>{researchPanel.classList.remove('open');researchPanel.setAttribute('aria-hidden','true')};document.getElementById('copySession').onclick=async()=>{await navigator.clipboard?.writeText(JSON.stringify(session,null,2));toast('Session JSON copied')};
renderBriefing();renderOpportunityList();renderOpportunityDetail();renderEvidence();const requested=params.get('view');if(['briefing','opportunities','career'].includes(requested))showView(requested);log('prototype_loaded',{viewport:`${innerWidth}x${innerHeight}`});
